	"fmt"
	"time"

	lua "github.com/yuin/gopher-lua"
)

// ExecutePricingScript executes a user-provided Lua script to calculate the final price
// of a product based on the given context.
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	// Create a new Lua state
	L := lua.NewState()
	defer L.Close()

	// Security: Remove dangerous functions from the global environment
	// to prevent arbitrary code execution, file system access, etc.
	removeDangerousFunctions(L)

	// Set a maximum execution time for the script (e.g., 100ms)
	// to prevent denial-of-service attacks via infinite loops.
	timeoutCtx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()
	L.SetContext(timeoutCtx)

	// Load and execute the script
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to execute Lua script: %w", err)
	}

	// Get the calculate_final_price function from global scope
	fn := L.GetGlobal("calculate_final_price")
	if fn.Type() != lua.LTFunction {
		return 0, fmt.Errorf("calculate_final_price is not a function or not defined")
	}

	// Convert Go context map to Lua table
	ctxTable := L.NewTable()
	for k, v := range ctx {
		L.SetField(ctxTable, k, lua.LNumber(v))
	}

	// Call the function with the context table
	if err := L.CallByParam(lua.P{
		Fn:      fn,
		NRet:    1,
		Protect: true,
	}, ctxTable); err != nil {
		return 0, fmt.Errorf("failed to call calculate_final_price: %w", err)
	}

	// Get the result from the Lua stack
	result := L.Get(-1)
	L.Pop(1) // Remove the result from the stack

	// Convert result to float64
	if result.Type() != lua.LTNumber {
		return 0, fmt.Errorf("calculate_final_price did not return a number")
	}

	return float64(result.(lua.LNumber)), nil
}

// removeDangerousFunctions removes or replaces dangerous functions from the Lua global
// environment to prevent malicious scripts from accessing the file system, executing
// system commands, or performing other harmful operations.
func removeDangerousFunctions(L *lua.LState) {
	// Get the global table
	globals := L.Get(lua.GlobalsIndex).(*lua.LTable)

	// List of dangerous modules/functions to remove
	dangerousKeys := []string{
		"os",
		"io",
		"require",
		"loadfile",
		"dofile",
		"load",
		"package",
		"debug",
	}

	for _, key := range dangerousKeys {
		globals.RawSetString(key, lua.LNil)
	}

	// Override the string library's dangerous functions if present
	stringLib := L.GetGlobal("string")
	if tbl, ok := stringLib.(*lua.LTable); ok {
		tbl.RawSetString("dump", lua.LNil)
	}
}

