// ExecutePricingScript executes a user-provided Lua script to calculate the final price.
// It takes the Lua script as a string and a map of context variables (e.g., base price, user tier).
// The Lua script must define a global function named `calculate_final_price` which accepts
// a table (the context) and returns a number (the final price).
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	// Create a new Lua VM
	L := lua.NewState()
	defer L.Close()

	// Execute the user-provided script to define the calculate_final_price function
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to execute Lua script: %w", err)
	}

	// Retrieve the global function calculate_final_price
	fn := L.GetGlobal("calculate_final_price")
	if fn.Type() != lua.LTFunction {
		return 0, fmt.Errorf("calculate_final_price is not a function, got %s", fn.Type().String())
	}

	// Convert the context map to a Lua table
	ctxTable := L.NewTable()
	for key, value := range ctx {
		L.SetField(ctxTable, key, lua.LNumber(value))
	}

	// Call the Lua function with the context table
	if err := L.CallByParam(lua.P{
		Fn:      fn,
		NRet:    1,
		Protect: true,
