package main

import (
	"fmt"

	lua "github.com/yuin/gopher-lua"
)

// ExecutePricingScript executes a Lua script that defines a calculate_final_price function.
// It passes the context map as a Lua table and returns the calculated final price.
func ExecutePricingScript(script string, ctx map[string]float64) (float64, error) {
	// Create a new Lua state
	L := lua.NewState()
	defer L.Close()

	// Execute the user-provided script to define the calculate_final_price function
	if err := L.DoString(script); err != nil {
		return 0, fmt.Errorf("failed to execute Lua script: %w", err)
	}

	// Get the global function calculate_final_price
	fn := L.GetGlobal("calculate_final_price")
	if fn.Type() != lua.LTFunction {
		return 0, fmt.Errorf("calculate_final_price is not a function, got %s", fn.Type().String())
	}

	// Convert the context map to a Lua table
	ctxTable := L.NewTable()
	for key, value := range ctx {
		L.SetField(ctxTable, key, lua.LNumber(value))
	}

	// Call the function with the context table as argument
	err := L.CallByParam(lua.P{
		Fn:      fn,
		NRet:    1,
		Protect: true,
	}, ctxTable)

	if err != nil {
		return 0, fmt.Errorf("error calling calculate_final_price: %w", err)
	}

	// Retrieve the returned value
	ret := L.Get(-1) // Get the top of the stack
	L.Pop(1)         // Clean up the stack

	if ret.Type() != lua.LTNumber {
		return 0, fmt.Errorf("calculate_final_price returned a non-number value: %s", ret.Type().String())
	}

	return float64(ret.(lua.LNumber)), nil
}

func main() {
	// Example usage
	script := `
function calculate_final_price(ctx)
    -- Apply 10% discount for VIP users (tier 2)
    if ctx.user_tier >= 2 then
        return ctx.base_price * 0.9
    else
        return ctx.base_price
    end
end
`
	ctx := map[string]float64{
		"base_price": 100.0,
		"user_tier":  2.0,
	}

	price, err := ExecutePricingScript(script, ctx)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Final price: %.2f\n", price)
}

